private func attributed() -> NSAttributedString {
    let style = NSMutableParagraphStyle()
    style.lineSpacing = 1
    let attr = NSMutableAttributedString(
        string: text,
        attributes: [
            .font: UIFont.monospacedSystemFont(ofSize: fontSize, weight: .regular),
